{
    "$meta": {
        "extensible": false
    },
    "世界": {
        "名字": [
            "艾瑞斯大陆",
            "当前世界或位面的名称，可由USER在开局时自定义。"
        ],
        "世界观": [
            "一个剑与魔法共存的幻想世界，神明在云端俯瞰，深渊在地下觊觎，人类、精灵、兽人等多种族在大陆上建立各自的文明。",
            "对世界基本背景的描述，可由USER在开-局时自定义。"
        ],
        "力量体系": [
            "本世界的力量以'源力'为基础，通过精神共鸣引导，可以显化为'斗气'或'魔法'等多种形式。力量的强弱通常用'战斗力'数值来量化。\n【战斗力等级划分参考】:\n- 1 ~ 99 (黑铁阶): 普通人与初学者，能勉强对抗野兽。\n- 100 ~ 499 (青铜阶): 正式踏入超凡门槛的战士或法师学徒。\n- 500 ~ 1999 (白银阶): 经验丰富的冒险者，军队中的精英。\n- 2000 ~ 9999 (黄金阶): 一方强者，足以担任城邦的守护者或独当一面。\n- 10000 ~ 49999 (传奇阶): 名震大陆的英雄人物，拥有改变局部战争走向的能力。\n- 50000+ (圣域/神话阶): 如同在世神明，其存在本身就是一种威慑。",
            "对本世界力量本质、形式和等级的详细描述，可由USER在开局时自定义。"
        ],
        "时间": [
            "帝国历 778年 春之月 1日 清晨",
            "当前的游戏内时间，需根据剧情流逝进行更新。"
        ],
        "当前位置": [
            "未知",
            "女主角当前所在的具体地点，随剧情移动更新。"
        ]
    },
    "USER": {
        "身份": [
            "灵魂绑定系统",
            "USER在本世界中扮演的具体角色，如'魔法契约兽'、'一把神剑'、'神秘老爷爷的灵魂'等，由USER在开局时自定义。"
        ],
        "存在形式": [
            "以女主角脑海中的声音或眼前浮现的虚拟面板形式存在，无法被他人感知。",
            "USER如何与女主角及世界互动的方式。"
        ],
        "契约形式": [
            "灵魂绑定",
            "USER与女主角之间的绑定关系。"
        ]
    },
    "女主角": {
        "基本档案": {
            "姓名": [
                "暂无",
                "女主角的名字，可由USER在开局时自定义。"
            ],
            "年龄": [
                16,
                "女主角的当前年龄。"
            ],
            "种族": [
                "暂无",
                "女主角的种族。"
            ],
            "职业": [
                "无",
                "女主角的当前职业或身份。"
            ]
        },
        "外貌描述": [
            "暂无详细描述",
            "详细描述女主角的外貌特征，会随装备和成长变化。"
        ],
        "性格特质": [
            "暂无详细描述",
            "描述女主角的核心性格，会随经历和USER的引导发生变化。"
        ],
        "身体状态": {
            "生命值": [
                [50, 50],
                "[当前值, 最大值]。归零则陷入濒死或死亡。"
            ],
            "能量值": [
                [30, 30],
                "[当前值, 最大值]。代表魔力、灵力、内力等用于施放技能的能量。"
            ],
            "正面状态": [
                ["$__META_EXTENSIBLE__$"],
                "记录力量祝福、迅捷加持等增益效果。可扩展数组。"
            ],
            "负面状态": [
                ["$__META_EXTENSIBLE__$"],
                "记录中毒、诅咒、虚弱等异常状态。可扩展数组。"
            ]
        },
        "核心属性": {
            "力量": [5, "影响物理攻击力与负重。"],
            "敏捷": [5, "影响攻击速度、闪避率和反应能力。"],
            "体质": [5, "影响生命值上限和物理防御力。"],
            "智力": [5, "影响能量攻击力、能量值上限和学习能力。"],
            "精神": [5, "影响能量防御力、异常状态抗性和能量恢复速度。"],
            "战斗力": [
                10,
                "综合衡量女主角当前战斗能力的数值。该数值通常由核心属性、装备、技能等综合计算得出，也可由特定事件或强化直接提升。"
            ]
        },
        "积分": [
            0,
            "用于在'系统商城'中购买物品的货币。主要通过完成任务或USER直接发放获得。"
        ],
        "装备": {
            "武器": ["无", "无效果"],
            "头部": ["无", "无效果"],
            "身体": ["无", "无效果"],
            "腿部": ["无", "无效果"],
            "饰品": ["无", "无效果"]
        },
        "技能": [
            ["$__META_EXTENSIBLE__$"],
            "女主角当前掌握的技能列表。可通过学习或任务奖励添加新技能。"
        ],
        "道具": [
            ["$__META_EXTENSIBLE__$"],
            "女主角的物品栏。可通过购买、采集或任务奖励增删物品。"
        ],
        "当前任务": [
            ["$__META_EXTENSIBLE__$"],
            "记录女主角当前正在进行的任务列表。任务由USER发布，完成后移除。"
        ]
    },
    "特殊数据": {
        "认可度": [
            50,
            "代表USER对女主角的评价值。范围0-100。\n**[最高优先级规则] 此数值的增减【完全】由USER【直接决定】，AI禁止修改。"
        ]
    }
}
